"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["11165"],{9833(e){e.exports=JSON.parse('{"id":"F468","slug":"insurtech-automation-savings","name":"Insurtech: Underwriting Result after Automation","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Insurtech","level":"Intermediate","aliases":["insurtech","claims automation","loss ratio","expense ratio","straight-through processing"],"formula":{"latex":"CR=LR+ER,\\\\quad \\\\Delta CR=-\\\\,a_{L}LR-a_{E}ER,\\\\quad UW=P(1-CR)","also":[],"text":"Combined ratio = loss ratio + expense ratio; Underwriting profit = premiums x (1 - combined ratio); New loss ratio = old x (1 - claims improvement from better pricing and fraud detection); New expense ratio = old x (1 - expense saving from automation)"},"symbols":[{"symbol":"LR","meaning":"Claims paid divided by premiums","unit":"percent"},{"symbol":"ER","meaning":"Operating expenses divided by premiums","unit":"percent"},{"symbol":"a_L, a_E","meaning":"Share by which technology cuts claims cost and expenses","unit":"percent"}],"when_to_use":"Use it to size what technology can do to an insurer\'s profit. Better pricing and fraud detection act on the loss ratio; automated claims and onboarding act on the expense ratio. A combined ratio below 100% is an underwriting profit. The gains are estimates from pilots and may not carry across the whole book.","worked_example":{"problem":"An insurer collects 800m of premiums, pays 620m of claims and spends 210m on expenses. Technology is expected to cut claims by 4% and expenses by 10%.","inputs":{"p":800000000,"c":620000000,"e":210000000,"al":4,"ae":10},"steps":[{"label":"Loss ratio now","working":"620,000,000 / 800,000,000","value":"77.5%"},{"label":"Expense ratio now","working":"210,000,000 / 800,000,000","value":"26.2%"},{"label":"Combined ratio now","working":"0.775+0.2625","value":"103.8%"},{"label":"Underwriting result now","working":"800,000,000 x (1-1.0375)","value":"-30,000,000.00"},{"label":"Loss ratio after","working":"0.775 x (1-0.04)","value":"74.4%"},{"label":"Expense ratio after","working":"0.2625 x (1-0.1)","value":"23.6%"},{"label":"Combined ratio after","working":"0.744+0.23625","value":"98.0%"},{"label":"Underwriting result after","working":"800,000,000 x (1-0.98025)","value":"15,800,000.00"},{"label":"Gain","working":"15,800,000--30,000,000","value":"45,800,000.00"}],"answer":"The combined ratio is 103.8% and the underwriting result is -30,000,000.00. After the changes the loss ratio is 74.4%, the expense ratio 23.6%, and the combined ratio 98.0%, giving an underwriting result of 15,800,000.00, a gain of 45,800,000.00."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Premiums","unit":"money","type":"number","default":800000000,"hint":""},{"id":"c","label":"Claims paid","unit":"money","type":"number","default":620000000,"hint":""},{"id":"e","label":"Expenses","unit":"money","type":"number","default":210000000,"hint":""},{"id":"al","label":"Cut in claims cost","unit":"%","type":"number","default":4,"hint":""},{"id":"ae","label":"Cut in expenses","unit":"%","type":"number","default":10,"hint":""}],"checks":[{"expr":"p>0","message":"Premiums must be above zero."}],"steps":[{"id":"lr0","label":"Loss ratio now","expr":"c/p","format":"pct1"},{"id":"er0","label":"Expense ratio now","expr":"e/p","format":"pct1"},{"id":"cr0","label":"Combined ratio now","expr":"lr0+er0","format":"pct1"},{"id":"uw0","label":"Underwriting result now","expr":"p*(1-cr0)","format":"money"},{"id":"lr1","label":"Loss ratio after","expr":"lr0*(1-al)","format":"pct1"},{"id":"er1","label":"Expense ratio after","expr":"er0*(1-ae)","format":"pct1"},{"id":"cr1","label":"Combined ratio after","expr":"lr1+er1","format":"pct1"},{"id":"uw1","label":"Underwriting result after","expr":"p*(1-cr1)","format":"money"},{"id":"gain","label":"Gain","expr":"uw1-uw0","format":"money"}],"results":["cr0","cr1","uw1","gain"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"lr0":0.775,"er0":0.2625,"cr0":1.0375,"uw0":-30000000.000000026,"lr1":0.744,"er1":0.23625000000000002,"cr1":0.9802500000000001,"uw1":15799999.999999993,"gain":45800000.000000015}},"finder":{"finds":"How much technology changes an insurer\'s underwriting profit","needs":"Premiums, claims, expenses, expected improvement"},"related":[{"slug":"combined-ratio","name":"Combined Ratio (Insurers)"},{"slug":"insurance-float-profit","name":"Insurance Underwriting Profit and Float"},{"slug":"expected-value","name":"Expected Value"}],"related_ids":["F221","F365","F058"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>C</mi><mi>R</mi><mo>=</mo><mi>L</mi><mi>R</mi><mo>+</mo><mi>E</mi><mi>R</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi mathvariant=\\"normal\\">\u0394</mi><mi>C</mi><mi>R</mi><mo>=</mo><mo>\u2212</mo><mtext>\u2009</mtext><msub><mi>a</mi><mi>L</mi></msub><mi>L</mi><mi>R</mi><mo>\u2212</mo><msub><mi>a</mi><mi>E</mi></msub><mi>E</mi><mi>R</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>U</mi><mi>W</mi><mo>=</mo><mi>P</mi><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>C</mi><mi>R</mi><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">CR=LR+ER,\\\\quad \\\\Delta CR=-\\\\,a_{L}LR-a_{E}ER,\\\\quad UW=P(1-CR)</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"insurance-float-profit","name":"Insurance Underwriting Profit and Float"},"next":{"slug":"loan-interest-split","name":"Interest and Principal in a Loan Payment"},"lesson":null,"total":522}')}}]);